116→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
117→  const { t } = useTranslation();
118→  const { isStreaming, editMessage, deleteMessage } = useAgent();
119→  const [isEditing, setIsEditing] = useState(false);
120→  const [editText, setEditText] = useState(message.content);
121→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
122→  const textareaRef = useRef<HTMLTextAreaElement>(null);
123→
124→  const isUser = message.role === 'user';
125→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
126→
127→  useEffect(() => {
128→    if (isEditing && textareaRef.current) {
129→      textareaRef.current.focus();
130→      textareaRef.current.selectionStart = textareaRef.current.value.length;
131→    }
132→  }, [isEditing]);
133→
134→  const handleEdit = () => {
135→    setEditText(message.content);
136→    setIsEditing(true);
137→    setIsConfirmingDelete(false);
138→  };
139→
140→  const handleCancelEdit = () => {
141→    setIsEditing(false);
142→    setEditText(message.content);
143→  };
144→
145→  const handleSaveEdit = () => {
146→    const trimmed = editText.trim();
147→    if (!trimmed || trimmed === message.content) {
148→      handleCancelEdit();
149→      return;
150→    }
151→    setIsEditing(false);
152→    editMessage(messageIndex, trimmed);
153→  };
154→
155→  const handleDeleteConfirm = () => {
156→    setIsConfirmingDelete(false);
157→    deleteMessage(messageIndex);
158→  };
159→
160→  const handleKeyDown = (e: React.KeyboardEvent) => {
161→    if (e.key === 'Escape') {
162→      handleCancelEdit();
163→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
164→      e.preventDefault();
165→      handleSaveEdit();
166→    }
167→  };
168→
169→  let streamingRemainder: string | undefined;
170→  if (hasSegments && message.isStreaming && message.content) {
171→    const segmentedText = message.segments!
172→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
173→      .map((s) => s.text || '')
174→      .join('');
175→    const remaining = message.content.slice(segmentedText.length);
176→    if (remaining.trim()) {
177→      streamingRemainder = remaining;
178→    }
179→  }
180→
181→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
182→  const isInAnswerPhase = message.currentPhase === 'answer';
183→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
184→
185→  const hasCharts = hasSegments && message.segments!.some(
186→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
187→  );
188→
189→  const answerSegments = hasSegments
190→    ? message.segments!
191→        .filter((s) => s.type === 'answer' && s.text?.trim())
192→        .map((s) => hasCharts ? { ...s, text: stripChartSpecBlocks(s.text!) } : s)
193→        .filter((s) => s.text?.trim())
194→    : [];
195→
196→  const chartSegments = hasSegments
197→    ? message.segments!.filter(
198→        (s) =>
199→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
200→          (s.type === 'subagent_end' && s.chart_spec)
201→      )
202→    : [];
203→
204→  return (
205→    <div className={`message-bubble message-bubble--${message.role}`}>
206→      <div className="message-bubble__header">
207→        {isUser ? t('you') : t('assistant')}
208→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
209→          <span className="message-bubble__actions">
210→            <button
211→              className="message-bubble__action-btn"
212→              onClick={handleEdit}
213→              title={t('editMessage')}
214→            >
215→              &#9998;
216→            </button>
217→            <button
218→              className="message-bubble__action-btn message-bubble__action-btn--delete"
219→              onClick={() => setIsConfirmingDelete(true)}
220→              title={t('deleteMessage')}
221→            >
222→              &#128465;
223→            </button>
224→          </span>
225→        )}
226→      </div>
227→
228→      {isUser && isConfirmingDelete && (
229→        <div className="message-bubble__confirm-delete">
230→          <span>{t('deleteConfirm')}</span>
231→          <div className="message-bubble__confirm-actions">
232→            <button
233→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
234→              onClick={handleDeleteConfirm}
235→            >
236→              {t('delete')}
237→            </button>
238→            <button
239→              className="message-bubble__confirm-btn"
240→              onClick={() => setIsConfirmingDelete(false)}
241→            >
242→              {t('cancel')}
243→            </button>
244→          </div>
245→        </div>
246→      )}
247→
248→      {isUser && isEditing ? (
249→        <div className="message-bubble__edit-mode">
250→          <textarea
251→            ref={textareaRef}
252→            className="message-bubble__edit-textarea"
253→            value={editText}
254→            onChange={(e) => setEditText(e.target.value)}
255→            onKeyDown={handleKeyDown}
256→            rows={3}
257→          />
258→          <div className="message-bubble__edit-actions">
259→            <button
260→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
261→              onClick={handleSaveEdit}
262→            >
263→              {t('saveResend')}
264→            </button>
265→            <button
266→              className="message-bubble__edit-btn"
267→              onClick={handleCancelEdit}
268→            >
269→              {t('cancel')}
270→            </button>
271→          </div>
272→        </div>
273→      ) : hasSegments ? (
274→        <div className="message-bubble__segments">
275→          <ThinkingBlock
276→            segments={message.segments!}
277→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
278→            isThinkingPhase={isThinkingPhase}
279→            isAgentStreaming={!!message.isStreaming}
280→          />
281→          {(chartSegments.length > 0 || answerSegments.length > 0) && (
282→            <div className="message-bubble__segment message-bubble__segment--answer">
283→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
284→              {chartSegments.map((seg, i) => (
285→                <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
286→                  {seg.type === 'tool' && seg.toolResult ? (
287→                    <InlineQueryResult result={seg.toolResult!} />
288→                  ) : seg.chart_spec ? (
289→                    <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} />
290→                  ) : null}
291→                </div>
292→              ))}
293→              {answerSegments.map((seg, i) => (
294→                <div key={`answer-${i}`} className="message-bubble__segment-content">
295→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
296→                </div>
297→              ))}
298→            </div>
299→          )}
300→          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (() => {
301→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
302→            return displayText?.trim() ? (
303→              <div className="message-bubble__segment message-bubble__segment--answer">
304→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
305→                <div className="message-bubble__segment-content">
306→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
307→                </div>
308→              </div>
309→            ) : null;
310→          })()}
311→          {message.isStreaming && !message.content && (
312→            <span className="message-bubble__typing">{t('thinking')}</span>
313→          )}
314→        </div>
315→      ) : (
316→        <>
317→          <div className="message-bubble__content">
318→            {message.content ? (
319→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
320→            ) : message.isStreaming ? (
321→              <span className="message-bubble__typing">{t('thinking')}</span>
322→            ) : null}
323→          </div>
324→          {message.toolCalls && message.toolCalls.length > 0 && (
325→            <div className="message-bubble__tools">
326→              {message.toolCalls.map((tc) => (
327→                <InlineQueryResult key={tc.toolCallId} result={tc} />
328→              ))}
329→            </div>
330→          )}
331→        </>
332→      )}
333→    </div>
334→  );
335→}
