 1→import { createContext, useContext } from 'react';
 2→import type { ChatMessage } from '../types';
 3→
 4→interface AgentContextValue {
 5→  messages: ChatMessage[];
 6→  isStreaming: boolean;
 7→  sendMessage: (text: string) => void;
 8→  editMessage: (messageIndex: number, newContent: string) => void;
 9→  deleteMessage: (messageIndex: number) => void;
10→  clearMessages: () => void;
11→  respondToQuestion: (questionId: string, answers: string[], freeText?: string) => void;
12→}
13→
14→export const AgentContext = createContext<AgentContextValue>({
15→  messages: [],
16→  isStreaming: false,
17→  sendMessage: () => {},
18→  editMessage: () => {},
19→  deleteMessage: () => {},
20→  clearMessages: () => {},
21→  respondToQuestion: () => {},
22→});
23→
24→export function useAgent() {
25→  return useContext(AgentContext);
26→}
